using Codex.ContentImport.Degrees;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Core;
using UglyToad.PdfPig.Fonts.Standard14Fonts;
using UglyToad.PdfPig.Writer;
using YamlDotNet.Serialization;

namespace Codex.Tests;

/// <summary>
/// Chapter 1's pipeline over synthetic input: the take-list, page-side furniture, openers, sidebars, tables, columns, the take stage's failures, entry
/// parsing, the pack emitter and its --check, and the denylist words. CI never sees a book: every PDF here is generated by the test.
/// </summary>
public class DegreesChapterOneTests : IDisposable
{
    private readonly string _temp = Path.Combine(Path.GetTempPath(), "CodexDegreesCh1_" + Guid.NewGuid());

    public DegreesChapterOneTests() => Directory.CreateDirectory(_temp);

    public void Dispose()
    {
        if (Directory.Exists(_temp)) Directory.Delete(_temp, true);
    }

    private const string Roles = """
        rules:
          - { role: furniture, family: [Helvetica-Bold], size: [12, 12], x: [0, 60], parity: odd }
          - { role: furniture, family: [Helvetica-Bold], size: [12, 12], x: [540, 700], parity: even }
          - { role: entry-header, family: [Helvetica-Bold], size: [13, 13] }
          - { role: section, family: [Helvetica-Bold], size: [16, 16] }
          - { role: block-header, family: [Helvetica-Bold], size: [11, 11] }
          - { role: tag, family: [Courier-Bold], size: [1, 9] }
          - { role: opener, family: [Courier-Oblique], size: [1, 20] }
          - { role: rules, family: [Times], size: [1, 11] }
          - { role: body, family: [Helvetica], size: [1, 11] }
        """;

    private const string TakeYaml = """
        rows:
          - { chapter: things, book: pc, parser: entries, target: condition, approved: true, paths: [[Appendix, List]] }
        """;

    private const string NoRedactions = "normalization: 2\nrows: []\n";

    private static List<SpineNode> ChapterSpine(bool sidebar = true) => new()
    {
        new SpineNode(0, "Appendix", new[] { "Appendix" }, 1, 2, false),
        new SpineNode(1, "List", new[] { "Appendix", "List" }, 1, 2, false),
        new SpineNode(2, "Sidebar: side title", new[] { "Appendix", "List", "Sidebar: side title" }, 2, 2, sidebar),
        new SpineNode(0, "Next", new[] { "Next" }, 3, 3, false),
    };

    private enum Variant { Normal, StrayHeading, OneColumn }

    /// <summary>Three pages: a chapter title, an opener and four entries on the first two (one with a sidebar and a table), and an untaken section on the third.</summary>
    private static byte[] ChapterBook(Variant variant = Variant.Normal)
    {
        var b = new PdfDocumentBuilder();
        var hel = b.AddStandard14Font(Standard14Font.Helvetica);
        var helBold = b.AddStandard14Font(Standard14Font.HelveticaBold);
        var times = b.AddStandard14Font(Standard14Font.TimesRoman);
        var timesBold = b.AddStandard14Font(Standard14Font.TimesBold);
        var courBold = b.AddStandard14Font(Standard14Font.CourierBold);
        var courItalic = b.AddStandard14Font(Standard14Font.CourierOblique);

        var p1 = b.AddPage(603, 783);
        p1.AddText("14", 12, new PdfPoint(30, 40), helBold);
        p1.AddText("A faraway tale that is dropped", 12, new PdfPoint(60, 745), courItalic);
        p1.AddText("List", 16, new PdfPoint(60, 720), helBold);
        p1.AddText("Alpha", 13, new PdfPoint(60, 690), helBold);
        p1.AddText("You are dazed and cannot act well while the exam-", 9, new PdfPoint(60, 676), times);
        p1.AddText("ple effect ends.", 9, new PdfPoint(60, 665), times);
        p1.AddText("Special", 9, new PdfPoint(60, 654), timesBold);
        p1.AddText("Costs one more.", 9, new PdfPoint(100, 654), times);
        p1.AddText("Beta", 13, new PdfPoint(60, 630), helBold);
        p1.AddText("Fire Cold", 8, new PdfPoint(60, 616), courBold);
        p1.AddText("Pay [one-action] to end it (see page 12).", 9, new PdfPoint(60, 604), times);
        p1.AddText("Gamma [one-action]", 13, new PdfPoint(330, 690), helBold);
        p1.AddText("Rolls matter a great deal here.", 9, new PdfPoint(330, 676), times);

        var p2 = b.AddPage(603, 783);
        p2.AddText("15", 12, new PdfPoint(560, 40), helBold);
        p2.AddText("Delta", 13, new PdfPoint(60, 720), helBold);
        p2.AddText("Short text about delta.", 9, new PdfPoint(60, 706), times);
        p2.AddText("SIDE TITLE", 11, new PdfPoint(60, 680), helBold);
        p2.AddText("Sidebar words here.", 9, new PdfPoint(60, 668), hel);
        p2.AddText("Epsilon", 13, new PdfPoint(60, 640), helBold);
        p2.AddText("Last words of epsilon.", 9, new PdfPoint(60, 626), times);
        p2.AddText("Name", 11, new PdfPoint(330, 720), helBold);
        p2.AddText("Level", 11, new PdfPoint(430, 720), helBold);
        p2.AddText("Foo", 9, new PdfPoint(330, 708), hel);
        p2.AddText("3", 9, new PdfPoint(430, 708), hel);
        p2.AddText("Bar", 9, new PdfPoint(330, 697), hel);
        p2.AddText("5 plus", 9, new PdfPoint(430, 697), hel);
        p2.AddText("extra", 9, new PdfPoint(430, 686), hel);
        p2.AddText("Baz", 9, new PdfPoint(330, 675), hel);
        p2.AddText("7", 9, new PdfPoint(430, 675), hel);
        if (variant == Variant.StrayHeading)
        {
            p2.AddText("Stray heading", 16, new PdfPoint(60, 590), helBold);
        }

        if (variant == Variant.OneColumn)
        {
            var wide = string.Join(' ', Enumerable.Repeat("wordy", 22));
            foreach (var y in new[] { 560, 549, 538 })
            {
                p2.AddText(wide, 9, new PdfPoint(60, y), times);
            }
        }

        var p3 = b.AddPage(603, 783);
        p3.AddText("17", 12, new PdfPoint(30, 40), helBold);
        p3.AddText("Next", 16, new PdfPoint(60, 720), helBold);
        p3.AddText("Not taken at all.", 9, new PdfPoint(60, 700), times);
        return b.Build();
    }

    private static (BlocksResult Blocks, List<SpineNode> Spine, List<TakeRow> Rows) Prepare(byte[] pdf, List<SpineNode> spine)
    {
        using var doc = PdfDocument.Open(pdf);
        var layout = LayoutStage.Run(doc, FontRoles.Parse(Roles));
        Assert.Empty(layout.Unclassified);
        var rows = TakeList.Parse(TakeYaml).Rows;
        return (BlocksStage.Run(layout.Pages, ImportPipeline.OptionsFor(spine, rows)), spine, rows);
    }

    // ---- options

    [Fact]
    public void Options_TakeAnOutFolderAndACheckFlag()
    {
        var run = DegreesOptions.Parse(new[] { "--book", "pc", "--pdf", "a.pdf", "--out", "pack", "--check" });
        Assert.Equal(("run", "pack", true), (run!.Action, run.Out, run.Check));

        var plain = DegreesOptions.Parse(new[] { "--book", "pc", "--pdf", "a.pdf", "--out", "pack" });
        Assert.False(plain!.Check);

        var denylist = DegreesOptions.Parse(new[] { "denylist", "--book", "mc", "--pdf", "b.pdf", "--out", "hashes.sha256" });
        Assert.Equal(("denylist", "hashes.sha256"), (denylist!.Action, denylist.Out));
    }

    // ---- font rules by page side

    [Fact]
    public void FontRules_CanBeLimitedToOddOrEvenPages()
    {
        var roles = FontRoles.Parse(Roles);
        Assert.Equal("furniture", roles.Classify("Helvetica-Bold", 12, 30, 1));
        Assert.Null(roles.Classify("Helvetica-Bold", 12, 30, 2));
        Assert.Equal("furniture", roles.Classify("Helvetica-Bold", 12, 560, 2));
        Assert.Null(roles.Classify("Helvetica-Bold", 12, 560, 1));
        Assert.Null(roles.Classify("Helvetica-Bold", 12, 30)); // a rule with a parity needs a page number
    }

    [Fact]
    public void Furniture_IsOnTheOuterEdgeOfEachSide_AndAPageNumberOnTheWrongSideHasNoRole()
    {
        var b = new PdfDocumentBuilder();
        var helBold = b.AddStandard14Font(Standard14Font.HelveticaBold);
        b.AddPage(603, 783).AddText("14", 12, new PdfPoint(30, 40), helBold);
        b.AddPage(603, 783).AddText("15", 12, new PdfPoint(30, 40), helBold);

        using var doc = PdfDocument.Open(b.Build());
        var layout = LayoutStage.Run(doc, FontRoles.Parse(Roles));

        Assert.Equal("furniture", layout.Pages[0].Words[0].Role);
        Assert.Equal("unclassified", layout.Pages[1].Words[0].Role);
        Assert.Equal(2, Assert.Single(layout.Unclassified).Letters);
    }

    // ---- blocks: openers, sidebars, tables, columns

    [Fact]
    public void Openers_AreDropped_CountedAndKeptOnlyForTheDenylist()
    {
        var (blocks, _, _) = Prepare(ChapterBook(), ChapterSpine());

        Assert.Equal(6, blocks.OpenerWords);
        Assert.DoesNotContain(blocks.Blocks, b => b.Role == "opener");
        var opener = Assert.Single(blocks.Dropped!, b => b.Role == "opener");
        Assert.Equal("A faraway tale that is dropped", opener.Lines.Single());
    }

    [Fact]
    public void Sidebars_AreSplitOutOnlyOnPagesASidebarBookmarkCovers()
    {
        var (blocks, _, _) = Prepare(ChapterBook(), ChapterSpine());
        Assert.Equal(2, blocks.SidebarBlocks);
        Assert.Equal(new[] { "block-header", "body" }, blocks.Dropped!.Where(b => b.Role != "opener").Select(b => b.Role));
        Assert.DoesNotContain(blocks.Blocks, b => b.Lines.Any(l => l.Contains("SIDE TITLE") || l.Contains("Sidebar words")));

        var (without, _, _) = Prepare(ChapterBook(), ChapterSpine(sidebar: false));
        Assert.Equal(0, without.SidebarBlocks);
        Assert.Contains(without.Blocks, b => b.Role == "block-header" && b.Lines.Single() == "SIDE TITLE");
    }

    [Fact]
    public void Tables_AreRebuiltFromWordBoxes_ColumnsFromTheHeaderRow_AndAWrappedCellJoinsItsRow()
    {
        var (blocks, _, _) = Prepare(ChapterBook(), ChapterSpine());

        var table = Assert.Single(blocks.Blocks, b => b.Role == "table");
        Assert.Equal(1, blocks.Tables);
        Assert.Equal(
            new[] { new[] { "Name", "Level" }, new[] { "Foo", "3" }, new[] { "Bar", "5 plus extra" }, new[] { "Baz", "7" } },
            table.Rows!.Select(r => r.ToArray()).ToArray());
        Assert.Equal(1, table.Column);
    }

    [Fact]
    public void ThreeColumns_AreSplitOnlyWhenAskedFor()
    {
        var b = new PdfDocumentBuilder();
        var hel = b.AddStandard14Font(Standard14Font.Helvetica);
        var page = b.AddPage(603, 783);
        for (var i = 0; i < 10; i++)
        {
            foreach (var x in new[] { 40, 230, 420 })
            {
                page.AddText("aa bb cc dd ee", 9, new PdfPoint(x, 700 - i * 11), hel);
            }
        }

        using var doc = PdfDocument.Open(b.Build());
        var layout = LayoutStage.Run(doc, FontRoles.Parse(Roles));

        var three = BlocksStage.Run(layout.Pages, new BlocksOptions { MaxColumns = _ => 3 });
        Assert.Equal(new[] { 0, 1, 2 }, three.Blocks.Select(blk => blk.Column).OrderBy(c => c));
        Assert.Equal(1, three.ThreeOrMoreColumnPages);

        var two = BlocksStage.Run(layout.Pages);
        Assert.Equal(2, two.Blocks.Select(blk => blk.Column).Distinct().Count());
        Assert.Equal(0, two.ThreeOrMoreColumnPages);
    }

    [Fact]
    public void AHeadingAcrossTheGutter_IsOneBlockInTheFirstColumn()
    {
        var b = new PdfDocumentBuilder();
        var hel = b.AddStandard14Font(Standard14Font.Helvetica);
        var helBold = b.AddStandard14Font(Standard14Font.HelveticaBold);
        var page = b.AddPage(603, 783);
        page.AddText("Wide", 16, new PdfPoint(190, 740), helBold);
        page.AddText("Title", 16, new PdfPoint(234, 740), helBold);
        for (var i = 0; i < 10; i++)
        {
            page.AddText("left text here", 9, new PdfPoint(60, 700 - i * 11), hel);
            page.AddText("right text here", 9, new PdfPoint(340, 700 - i * 11), hel);
        }

        using var doc = PdfDocument.Open(b.Build());
        var blocks = BlocksStage.Run(LayoutStage.Run(doc, FontRoles.Parse(Roles)).Pages);

        var heading = Assert.Single(blocks.Blocks, blk => blk.Role == "section");
        Assert.Equal(("Wide Title", 0), (heading.Lines.Single(), heading.Column));
    }

    // ---- the take-list

    [Fact]
    public void TakeList_TheCommittedListParses_AndOnlyBuiltParsersCanRun()
    {
        var list = TakeList.Embedded();
        Assert.NotEmpty(list.Rows);
        Assert.All(list.Rows, r => Assert.Contains(r.Parser, TakeList.BuiltParsers));
        Assert.Equal("conditions", list.For("pc").First().FolderName);
        Assert.Empty(list.For("mc"));
    }

    [Fact]
    public void TakeList_ReadsARowAndDefaultsTheFolderAndColumns()
    {
        var row = Assert.Single(TakeList.Parse(TakeYaml).Rows);
        Assert.Equal(("things", "entries", "condition", 2, true), (row.Chapter, row.Parser, row.Target, row.Columns, row.Approved));
        Assert.Equal("conditions", row.FolderName);
        Assert.Equal(new[] { "Appendix", "List" }, row.Paths.Single());
        Assert.Equal("accessories", new TakeRow { Target = "accessory" }.FolderName);
    }

    [Theory]
    [InlineData("rows: [{ chapter: a, book: pc, parser: magic, target: t, approved: false, paths: [[X]] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: t, approved: false, paths: [] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: t, approved: false, paths: [[]] }]")]
    [InlineData("rows: [{ chapter: a, book: xx, parser: entries, target: t, approved: false, paths: [[X]] }]")]
    [InlineData("rows: [{ chapter: A, book: pc, parser: entries, target: t, approved: false, paths: [[X]] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: Cond, approved: false, paths: [[X]] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: t, approved: false, columns: 9, paths: [[X]] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: t, approved: false, colums: 2, paths: [[X]] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: t, approved: false, paths: [[X], [x]] }]")]
    [InlineData("rows: [{ chapter: a, book: pc, parser: entries, target: t, approved: false, paths: [[X]] }, { chapter: b, book: pc, parser: rules, target: t, approved: false, paths: [[X]] }]")]
    [InlineData("rows: not-a-list")]
    public void TakeList_RejectsAMalformedRow(string yaml) => Assert.Throws<DegreesException>(() => TakeList.Parse(yaml));

    // ---- the take stage

    private static Block Blk(int page, int column, string role, params string[] lines) =>
        new(page, column, role, 60, 0, 300, 100, lines.ToList(), lines.Select(_ => new LineInfo(60, 300, string.Empty)).ToList());

    private static BlocksResult Result(IEnumerable<Block> blocks, params int[] oneColumn) =>
        new(blocks.ToList(), 0, 0, 0, new Dictionary<string, int>(), new List<int>(), new List<Block>(), oneColumn.ToList());

    private static readonly List<SpineNode> TwoSections = new()
    {
        new SpineNode(0, "Root", new[] { "Root" }, 1, 3, false),
        new SpineNode(1, "Sec A", new[] { "Root", "Sec A" }, 1, 1, false),
        new SpineNode(1, "Sec B", new[] { "Root", "Sec B" }, 1, 3, false),
    };

    private static TakeRow RowFor(string parser, params string[] path) =>
        new() { Chapter = "c", Book = "pc", Parser = parser, Target = "condition", Approved = true, Paths = { path.ToList() } };

    [Fact]
    public void TheRangeRunsFromAfterItsTitleToTheNextSiblingsTitle()
    {
        var blocks = Result(new[]
        {
            Blk(1, 0, "section", "Sec A"), Blk(1, 0, "entry-header", "One"), Blk(1, 0, "rules", "text"),
            Blk(1, 0, "section", "Sec B"), Blk(1, 0, "rules", "other"),
        });

        var range = Assert.Single(TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("entries", "Root", "Sec A") }));

        Assert.Equal((1, 3), (range.Start, range.End));
    }

    /// <summary>A root with <paramref name="children"/> bookmark children, <paramref name="sidebars"/> of them sidebars, and a range of <paramref name="headers"/> entry headers.</summary>
    private static (List<SpineNode> Spine, BlocksResult Blocks, List<TakenRange> Ranges) CountFixture(int children, int sidebars, int headers, string? countsDiffer = null)
    {
        var spine = new List<SpineNode> { new(0, "Root", new[] { "Root" }, 1, 3, false) };
        for (var i = 0; i < children; i++)
        {
            var sidebar = i < sidebars;
            var title = sidebar ? $"Sidebar {i}" : $"Child {i}";
            spine.Add(new SpineNode(1, title, new[] { "Root", title }, 1, 1, sidebar));
        }

        var blocks = Enumerable.Range(0, headers).Select(i => Blk(1, 0, "entry-header", $"E{i}")).ToList();
        var row = RowFor("entries", "Root");
        row.CountsDiffer = countsDiffer;
        return (spine, Result(blocks), new List<TakenRange> { new(row, 1, spine[0], 0, headers) });
    }

    [Fact]
    public void TheEntryCountsAgree_WhenBookmarkChildrenLessSidebarsEqualTheEntryHeaders_AsForTheFortyTwoConditions()
    {
        var (spine, blocks, ranges) = CountFixture(children: 46, sidebars: 4, headers: 42);

        Assert.Equal(new[] { (42, 42) }, ImportPipeline.CheckEntryCounts(spine, blocks, ranges));
    }

    [Fact]
    public void ADisagreementInTheEntryCountsFailsTheRunWithBothCounts_UnlessTheRowExplainsIt()
    {
        var (spine, blocks, ranges) = CountFixture(children: 46, sidebars: 4, headers: 41);

        var ex = Assert.Throws<DegreesException>(() => ImportPipeline.CheckEntryCounts(spine, blocks, ranges));
        Assert.Contains("42", ex.Message);
        Assert.Contains("41", ex.Message);

        var (spine2, blocks2, ranges2) = CountFixture(children: 46, sidebars: 4, headers: 41, countsDiffer: "One entry shares a header with the one above it.");
        Assert.Equal(new[] { (42, 41) }, ImportPipeline.CheckEntryCounts(spine2, blocks2, ranges2));
    }

    [Fact]
    public void ASectionWithNoChildBookmarksHasNothingToCompare()
    {
        var (spine, blocks, ranges) = CountFixture(children: 0, sidebars: 0, headers: 7);

        Assert.Empty(ImportPipeline.CheckEntryCounts(spine, blocks, ranges));
    }

    [Fact]
    public void AnEntryWhoseTitleIsItsOwnHeaderKeepsTheHeader()
    {
        var blocks = Result(new[] { Blk(1, 0, "entry-header", "Sec A"), Blk(1, 0, "rules", "text"), Blk(1, 0, "section", "Sec B") });

        var range = Assert.Single(TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("entries", "Root", "Sec A") }));

        Assert.Equal((0, 2), (range.Start, range.End));
    }

    [Fact]
    public void ASectionThatStartsOnAPageOfItsOwn_EndsTheRangeAtThePageBoundary()
    {
        var spine = new List<SpineNode>
        {
            new(0, "Root", new[] { "Root" }, 1, 2, false),
            new(1, "Sec A", new[] { "Root", "Sec A" }, 1, 1, false),
            new(1, "Sec C", new[] { "Root", "Sec C" }, 2, 2, false),
        };
        var blocks = Result(new[] { Blk(1, 0, "section", "Sec A"), Blk(1, 0, "entry-header", "One"), Blk(2, 0, "display", "Decor"), Blk(2, 0, "section", "Sec C") });

        var range = Assert.Single(TakeStage.Resolve(spine, blocks, new[] { RowFor("entries", "Root", "Sec A") }));
        Assert.Equal((1, 2), (range.Start, range.End));

        var tail = Result(new[] { Blk(1, 0, "section", "Sec A"), Blk(1, 0, "entry-header", "One"), Blk(2, 0, "rules", "tail"), Blk(2, 0, "section", "Sec C") });
        var ex = Assert.Throws<DegreesException>(() => TakeStage.Resolve(spine, tail, new[] { RowFor("entries", "Root", "Sec A") }));
        Assert.Contains("text sits above the next section's title", ex.Message);
    }

    [Fact]
    public void ABlockThatNoParserClaimsFailsTheRun_WithRoleAndPositionOnly()
    {
        var blocks = Result(new[]
        {
            Blk(1, 0, "section", "Sec A"), Blk(1, 0, "entry-header", "One"), Blk(1, 1, "block-header", "SECRET TEXT"), Blk(1, 1, "rules", "ok"), Blk(1, 1, "section", "Sec B"),
        });

        var ex = Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("entries", "Root", "Sec A") }));

        Assert.Contains("1 block(s) in the range that the entries parser does not claim", ex.Message);
        Assert.Contains("block-header on page 1 column 1", ex.Message);
        Assert.DoesNotContain("SECRET", ex.Message);
    }

    [Fact]
    public void AnEntriesRangeMustStartWithAnEntryHeader()
    {
        var blocks = Result(new[] { Blk(1, 0, "section", "Sec A"), Blk(1, 0, "rules", "loose text"), Blk(1, 0, "section", "Sec B") });

        Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("entries", "Root", "Sec A") }));
        Assert.Single(TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("rules", "Root", "Sec A") }));
    }

    [Fact]
    public void APathThatIsNotInTheBook_ATitleThatIsNotOnItsPage_AndAParserNotBuilt_AllFail()
    {
        var blocks = Result(new[] { Blk(1, 0, "section", "Sec A"), Blk(1, 0, "section", "Sec B") });

        Assert.Contains("no bookmark has that path", Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("entries", "Root", "Nope") })).Message);
        Assert.Contains("has the bookmark's title", Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, Result(new[] { Blk(1, 0, "rules", "x") }), new[] { RowFor("entries", "Root", "Sec A") })).Message);
        Assert.Contains("not built yet", Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("statblocks", "Root", "Sec A") })).Message);
    }

    [Fact]
    public void TwoRowsThatTakeTheSameBlocksFail()
    {
        var blocks = Result(new[] { Blk(1, 0, "section", "Sec A"), Blk(1, 0, "rules", "x"), Blk(1, 0, "section", "Sec B") });
        var rows = new[] { RowFor("rules", "Root", "Sec A"), RowFor("rules", "Root", "Sec A") };

        Assert.Contains("take the same blocks", Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, blocks, rows)).Message);
    }

    [Fact]
    public void AOneColumnPageInATakenRangeFails_UnlessTheRowSaysOneColumn()
    {
        var blocks = Result(new[] { Blk(1, 0, "section", "Sec A"), Blk(1, 0, "entry-header", "One"), Blk(1, 0, "section", "Sec B") }, 1);

        var ex = Assert.Throws<DegreesException>(() => TakeStage.Resolve(TwoSections, blocks, new[] { RowFor("entries", "Root", "Sec A") }));
        Assert.Contains("1 one-column page(s)", ex.Message);

        var row = RowFor("entries", "Root", "Sec A");
        row.Columns = 1;
        Assert.Single(TakeStage.Resolve(TwoSections, blocks, new[] { row }));
    }

    // ---- stage 4 and 5, from synthetic pages

    [Fact]
    public void TheChapterBook_ReadsIntoFourEntriesWithTheirPartsAndNothingOfTheNextSection()
    {
        var (blocks, spine, rows) = Prepare(ChapterBook(), ChapterSpine());

        var result = ImportPipeline.Run(blocks, spine, rows, RedactionTable.Parse(NoRedactions), "pc");

        Assert.Equal(new[] { "alpha", "beta", "delta", "epsilon", "gamma" }, result.Final.Select(e => e.Id));
        Assert.Equal(3, blocks.FurnitureWords);

        var alpha = result.Parsed.Single(e => e.Id == "alpha");
        Assert.Equal(new[] { "You are dazed and cannot act well while the example effect ends." }, alpha.Paragraphs);
        Assert.Equal(new[] { new LabelledText("Special", "Costs one more.") }, alpha.Fields);
        Assert.Equal("pc > Appendix > List", alpha.Source);

        var beta = result.Parsed.Single(e => e.Id == "beta");
        Assert.Equal(new[] { "Fire", "Cold" }, beta.Traits);
        Assert.Equal(new[] { "Pay [1 action] to end it." }, beta.Paragraphs);

        var gamma = result.Parsed.Single(e => e.Id == "gamma");
