    // ---- the emitter

    private static List<FinalEntry> SomeEntries() => new()
    {
        new FinalEntry { Id = "b-two", Type = "condition", Folder = "conditions", Source = "pc > Root > Sec", Name = "B two", Description = "First paragraph.\nSecond \"quoted\" paragraph." },
        new FinalEntry { Id = "a-one", Type = "condition", Folder = "conditions", Source = "pc > Root > Sec", Name = "A one", Description = "Single line: with a colon." },
        new FinalEntry { Id = "rule-x", Type = "rule", Folder = "rules", Source = "pc > Root > Rule", Name = "Rule X", Description = "Text.", Category = "Conditions" },
    };

    private static readonly List<ReportRow> SomeReport = new() { new ReportRow("things", "entries", "condition", 2, new List<string> { "b-two", "a-one" }, 1, 0, new List<int> { 3, 1 }, 0) };

    [Fact]
    public void TheEmitter_IsDeterministic_SortedById_AndWhatItWritesLoadsBackAsTheSameText()
    {
        var first = PackEmitter.Files(SomeEntries(), SomeReport);
        var second = PackEmitter.Files(SomeEntries().AsEnumerable().Reverse(), SomeReport);

        Assert.Equal(first, second);
        Assert.Equal(new[] { "conditions/conditions.yaml", "import-report.yaml", "rules/rules.yaml" }, first.Keys);

        var loaded = new DeserializerBuilder().Build().Deserialize<List<Dictionary<string, object>>>(first["conditions/conditions.yaml"]);
        Assert.Equal(new[] { "a-one", "b-two" }, loaded.Select(e => (string)e["id"]));
        Assert.Equal("First paragraph.\nSecond \"quoted\" paragraph.", (string)loaded[1]["description"]);
        Assert.Equal("Single line: with a colon.", (string)loaded[0]["description"]);
        var rule = new DeserializerBuilder().Build().Deserialize<List<Dictionary<string, object>>>(first["rules/rules.yaml"]).Single();
        Assert.Equal("Conditions", ((Dictionary<object, object>)rule["properties"])["category"]);

        var report = new DeserializerBuilder().Build().Deserialize<List<Dictionary<string, object>>>(first["import-report.yaml"]).Single();
        Assert.Equal(new[] { "1", "3" }, ((List<object>)report["redactionRows"]).Select(o => (string)o));
        Assert.Equal(new[] { "a-one", "b-two" }, ((List<object>)report["ids"]).Select(o => (string)o));
        Assert.DoesNotContain("paragraph", first["import-report.yaml"]);
    }

