    [Fact]
    public void RunStages_WritesThePack_ThenCheckPassesAndCatchesAHandEdit_AndWritesTheWorkFiles()
    {
        using var doc = PdfDocument.Open(ChapterBook());
        var spine = ChapterSpine();
        var take = TakeList.Parse(TakeYaml);
        var work = Path.Combine(_temp, "work");
        var pack = OwnPack();
        int Stages(bool check, StringWriter error) =>
            DegreesCommand.RunStages(doc, spine, FontRoles.Parse(Roles), work, new StringWriter(), error, take, "pc", RedactionTable.Parse(NoRedactions), pack, check);

        Assert.Equal(0, Stages(false, new StringWriter()));
        Assert.True(File.Exists(Path.Combine(pack, "conditions", "conditions.yaml")));
        Assert.True(File.Exists(Path.Combine(pack, "import-report.yaml")));
        Assert.All(new[] { "layout.json", "spine.json", "blocks.json", "entries.json", "redacted.json", "import-report.yaml" }, f => Assert.True(File.Exists(Path.Combine(work, f)), f));

        var before = File.ReadAllText(Path.Combine(pack, "conditions", "conditions.yaml"));
        Assert.Equal(0, Stages(true, new StringWriter()));
        Assert.Equal(before, File.ReadAllText(Path.Combine(pack, "conditions", "conditions.yaml")));

        File.WriteAllText(Path.Combine(pack, "conditions", "conditions.yaml"), before.Replace("Alpha", "Alfa"));
        using var error = new StringWriter();
        Assert.Equal(1, Stages(true, error));
        Assert.Contains("differs: conditions/conditions.yaml", error.ToString());
        Assert.Contains("Alfa", File.ReadAllText(Path.Combine(pack, "conditions", "conditions.yaml")));
    }

